"""Explain overlapping metadata moves, origin grouping, cache and depth limits."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1725': ('같은 줄의 칸을 오른쪽으로 옮길 때 앞칸부터 덮어쓰면 아직 읽지 않은 내용을 잃을 수 있어요. 뒤칸부터 옮기면 원본을 읽은 뒤 덮을 수 있어요.', '겹치는 복사에서 방향을 고르는 이유와 검증 기준을 이해합니다.', '[A,B,C,D,E]에서 앞 네 칸을 오른쪽 한 칸으로 옮기세요. 뒤부터 옮겨 [A,A,B,C,D]를 만드는 순서를 적으세요.', ['이 함수는 실제 데이터 복사에 맞춰 shadow라는 검사 정보를 옮겨요. src는 원본 시작, dst는 도착 시작, n은 옮길 바이트 수예요. 같은 메모리 안에서 두 범위가 겹치면 쓰는 순서가 중요해요.', '[A,B,C,D,E]의 앞 네 칸을 오른쪽으로 한 칸 옮긴다고 해 봐요. 앞부터 A를 두 번째 칸에 쓰면 B가 사라져요. 다음에 두 번째 칸을 읽으면 원래 B가 아니라 방금 쓴 A를 읽어서 잘못된 복사를 이어갈 수 있어요.', '뒤부터 하면 D를 마지막 칸에, C를 그 앞에, B를 그 앞에, A를 두 번째 칸에 써요. 아직 읽지 않은 원본을 먼저 덮지 않아서 결과는 [A,A,B,C,D]예요. 글자들은 서로 다른 shadow 바이트 값을 구별하기 위한 연습 표식이에요.', '본문은 dst>src이면 backwards를 참으로 놓고 step=-1,iter=n-1로 시작해요. n=4이면 인덱스3·2·1·0 순서예요. 그렇지 않으면 step=1,iter=0으로0·1·2·3 순서예요. 이 함수는 별도의 겹침 검사 결과가 아니라 시작 주소의 대소로 방향을 고른다는 점도 확인하세요.', '결과를 확인하려면 쓰기 전에 원본 shadow를 별도 종이에 복사해 두세요. 최종 도착지가 그 처음 기록과 같은지 비교하면 앞서 쓴 값 때문에 원본이 망가졌는지 알아볼 수 있어요. 이렇게 결과 판단에 쓰는 독립 기준을 oracle이라고 부르기도 해요.', '이 비교는 작은 정상 메모리 구간에서 shadow 이동이 맞는지 확인하는 방법이에요. 실제 커널의 페이지 할당, 모든 원인 정보 처리, 모든 크기의 복사를 한꺼번에 검증하는 것은 아니에요. 실제 데이터 이동과 검사 정보 이동도 구별해야 해요.'], [('dst가 src보다 높은 주소이면 이 코드의 복사 순서는 무엇인가요?', ['항상 앞에서 뒤로 가요', '끝 칸부터 시작하는 역방향이에요'], '정답은 두 번째예요. iter=n-1,step=-1로 정해요. 겹치는 오른쪽 이동에서 아직 읽지 않은 원본을 먼저 덮지 않도록 하는 순서예요.'), ('shadow 복사가 맞는지 비교할 독립 기준은 무엇인가요?', ['복사 전 shadow를 따로 보관해 만든 memmove 예상 결과예요', '커널의 전체 페이지 할당기 동작이에요'], '정답은 첫 번째예요. 덮어쓰기 전에 보관한 원본과 최종 도착지를 비교해요. 이 기준은 shadow 바이트 이동을 확인하며 커널 전체 실행을 검증하지는 않아요.')]), 'os1726': ('네 칸씩 묶인 상자에서 네 번째 칸 다음으로 가면 다음 상자예요. 복사를 시작한 칸이 상자 안 어디인지 알아야 올바른 원인 상자를 찾을 수 있어요.', '주소의 나머지와 바이트 위치로 원인 그룹 번호를 계산합니다.', '원본 offset1·도착 offset3에서 iter0과1을 대입해 원본 그룹0·0,도착 그룹0·1을 계산하세요.', ['shadow는 데이터 바이트를 하나씩 따라가고 origin은4바이트 묶음과 연결돼요. 따라서 지금 복사하는 바이트 번호와 원인 기록의 그룹 번호는 다를 수 있어요. 바이트는 작은 칸, origin 그룹은 네 칸짜리 묶음으로 그려 보세요.', 'src_off와 dst_off는 각각 원본·도착 주소를4로 나눈 나머지예요. %4는 시작 주소가 네 칸 묶음의0·1·2·3번째 중 어디인지 알려 줘요. iter는 복사 시작에서 몇 바이트 떨어진 위치를 다루는지 나타내요.', '원인 그룹 번호는 (iter+offset)/4로 계산해요. 정수 나눗셈이므로 소수점 아래는 버려요. dst_off=3,iter=0이면3/4=0이고 iter=1이면4/4=1이에요. 한 바이트 이동했지만 네 칸 경계를 넘어 원인 그룹도 다음으로 간 것이에요.', '원본 offset이1이면 iter0과1은 각각1/4=0,2/4=0이에요. 같은 복사 단계라도 원본은 아직 그룹0인데 도착지는 그룹1일 수 있어요. 그래서 원본과 도착지의 그룹 번호를 따로 계산해야 해요.', '도착지 shadow는 ALIGN_DOWN으로4바이트 경계 쪽으로 내려 잡은 주소도 이용해요. 그래야 현재 한 바이트뿐 아니라 그 바이트가 속한 네 칸 전체의 상태를 볼 수 있어요. 원본 shadow가0이면 도착 바이트도0으로 쓰고, 해당 네 칸 전체가0인지 확인해요.', '전체가0이면 origin도0으로 지워요. 하지만 [0,FF,0,0]처럼 다른 미준비 바이트가 남으면 원인 기록을 유지해야 해요. 한 칸이 준비됐다는 사실과 네 칸 전체가 준비됐다는 사실을 구별하는 검사예요.'], [('dst_off=3,iter=1의 원인 그룹 번호는 얼마인가요?', ['언제나0이에요', '(3+1)/4=1이에요'], '정답은 두 번째예요. 묶음 안 마지막 위치3에서 한 바이트 이동하면 다음 묶음이에요. iter 자체와 원인 그룹 번호는 같은 기준이 아니에요.'), ('준비된 shadow 바이트 하나를 복사하면 그룹 origin도 항상 지우나요?', ['아니요. 네 칸 shadow 전체가0인지 확인해요', '네. 다른 칸 상태와 관계없이 지워요'], '정답은 첫 번째예요. 다른 미준비 칸이 남으면 그 칸을 설명할 원인이 필요해요. 정렬된 도착지 shadow 묶음을 확인하는 이유예요.')]), 'os1727': ('방금 찾은 답을 작은 메모 한 장에 적어 두면 바로 같은 질문이 나올 때 다시 찾지 않아도 돼요. 이 메모는 모든 답을 영구히 모은 사전과는 달라요.', '직전 원인 연결 결과의 재사용과 실패 시 기존 기록 보존을 이해합니다.', '원인 A,A,B,A 순서에서 새 연결·재사용·새 연결·새 연결 시도를 적으세요. A와B는 서로 다른0이 아닌 원인 번호로 놓으세요.', ['미준비 shadow를 옮길 때는 원본의 원인 old_origin도 읽어요. chain_origin은 그 원인에 이번 복사 경로의 기록을 연결하려는 함수예요. 바이트마다 같은 연결 작업을 반복하면 불필요한 기록 저장 비용이 생길 수 있어요.', '그래서 함수 안에 prev_old_origin과 prev_new_origin 두 값을 둬요. 앞의 것은 직전에 처리한 기존 원인, 뒤의 것은 그 원인에서 얻은 연결 결과예요. 이렇게 최근 결과를 기억해 다시 쓰는 작은 저장을 cache라고 불러요.', '현재 old_origin이 기억한 prev_old_origin과 같으면 prev_new_origin을 그대로 써요. 서로 다르면 chain_origin을 호출해요. 예를 들어 서로 다른0이 아닌 원인 A,A,B,A 순서에서는 첫 A를 연결하고 둘째 A는 재사용해요. B 다음 A에서는 기억한 원인이B이므로 A도 다시 연결을 시도해요.', '이것은 함수 호출 안의 두 지역 변수예요. 모든 원인을 저장하는 전역 해시 테이블이나 영구 사전이 아니에요. 또 준비된 shadow0을 처리하는 경로는 이 두 값을 갱신하기 전에 continue하므로, 직전이라는 말은 이 캐시를 마지막으로 갱신한 원인을 뜻해요.', '새 연결 결과 new_origin이0이면 코드가 old_origin으로 대체해요. 새 정보를 붙이지 못해도 원래 알고 있던 원인까지 잃고 싶지 않기 때문이에요. 기존 원인77에 새 연결 결과0이면 최종 기록은77로 남아요.', '이후 도착 원인 칸에 결과를 쓰고 두 기억값도 갱신해요. 캐시는 같은 작업 반복을 줄이고, 실패 시 대체는 기존 정보를 보존하는 서로 다른 역할이에요. 새 원인 기록이 항상 생성되거나0이 아니라고 가정하지 마세요.'], [('이 캐시는 무엇을 기억하나요?', ['모든 원인의 전역 해시 테이블이에요', '직전 기존 원인과 그 연결 결과 두 값이에요'], '정답은 두 번째예요. 지역 변수 prev_old_origin과 prev_new_origin을 사용해요. 모든 과거 원인을 저장하지 않으므로 A,B,A에서는 마지막 A의 연결을 다시 시도해요.'), ('chain_origin이0을 돌려주면 기존 원인도 반드시 지우나요?', ['아니요. 기존 old_origin을 대신 써요', '네. 항상 origin0으로 지워요'], '정답은 첫 번째예요. if(!new_origin) new_origin=old_origin이 있어요. 새 연결을 못 얻더라도 이전에 알고 있던 원인 정보를 보존하려는 처리예요.')]), 'os1728': ('같은 물건을 여러 번 전달할 때 전달 메모를 끝없이 붙이면 메모만 계속 길어질 수 있어요. 원인 추적도 일정 깊이에 도달하면 기존 기록을 유지해요.', '원인 연결 깊이를 제한하는 이유와 정확한 종료 조건을 이해합니다.', '정상 깊이6이면 새 연결을 시도해7, 깊이7이면 기존 식별자 유지로 두 화살표를 그리세요.', ['origin chain은 준비되지 않은 값이 어떤 경로로 옮겨 왔는지 연결한 원인 기록이에요. handle 또는 id는 그 기록을 가리키는 식별자예요. 이 함수는 먼저 id가0이면 그대로0을 돌려줘요. 연결할 기존 원인 기록이 없는 경우를 먼저 처리해요.', '기록 식별자의 extra bits에서 현재 깊이와 UAF 표시를 꺼내요. UAF는 해제 후 사용과 관련된 표시예요. 고정 원본의 KMSAN_MAX_ORIGIN_DEPTH는7이에요. 깊이가 그 값과 같으면 새 기록을 만들지 않고 기존 id를 그대로 반환해요.', '왜 길이를 제한할까요? 구조체는 여러 필드를 묶은 자료형이고 컴파일러는 필드를 맞춰 배치하려 사이에 빈 바이트를 둘 수 있어요. 이 빈 공간을 padding이라고 해요. 필드에 값을 넣었어도 padding까지 모두 준비됐다고 자동으로 보장되지는 않아요.', '미준비 padding이 남은 구조체를 같은 경로로 반복 복사하면 원인 연결에도 비슷한 기록이 되풀이될 수 있어요. 이를 모두 저장하면 추적에 필요한 메모리와 작업량이 계속 늘어요. 원문은 이런 주기적인 연결을 끝까지 저장할 의미가 적어 상한을 둔다고 설명해요.', '정상 깊이6이면 깊이를1 늘려7인 새 연결 저장을 시도하고 UAF 표시도 보존해요. 깊이7이면 처음 기록을 유지해요. 깊이7에 도달했다고 데이터가 준비된 것으로 바뀌거나 이전 원인을 지우는 것은 아니에요. 새 연결을 더 늘리지 않는 것이에요.', '본문 비교는 depth==7이에요. 아무 잘못된 큰 깊이나 넣어도 전부7로 줄여 주는 >= 검사나 clamp는 아니에요. 허용된 식별자와 깊이 범위라는 호출 조건을 지켜야 해요. 새 연결 저장의 실패 처리도 호출한 쪽과 함께 읽어야 해요.'], [('정상 원인 기록의 깊이가7이면 새 연결을 계속 저장하나요?', ['네. 제한 없이 계속 늘려요', '아니요. 기존 id를 그대로 돌려줘요'], '정답은 두 번째예요. depth==KMSAN_MAX_ORIGIN_DEPTH이면 반환해요. 반복되는 원인 기록의 비용을 제한하면서 기존 기록은 남겨요.'), ('원문은 어떤 반복 복사를 상한의 예로 드나요?', ['준비되지 않은 padding을 가진 구조체의 반복 복사예요', '모든 프로세스 이름을 정렬하는 일이에요'], '정답은 첫 번째예요. padding은 구조체 배치를 맞추기 위한 빈 바이트예요. 같은 미준비 공간이 반복 전달되면 원인 기록도 되풀이되어 계속 늘릴 실익이 적을 수 있어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_427.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
